#pragma pack(push,1)
struct Header{char magic[8];uint32_t version,candidates,cases;};
struct Row{int32_t own_money,opp_money;uint16_t activations,rewrites,flags,pad;};
#pragma pack(pop)
struct CaseHost{std::string path;int seat=0;uint64_t seed=0;int family=0,protected_flag=0,own_history=0,role=0;};
struct CaseDev{int tape=0,seat=0;uint64_t seed=0;int family=0,protected_flag=0,own_history=0,role=0;};
struct OppDesc{int first=0,count=0;};
struct DevicePolicyOwner4{bonsaikg4::Node4*n=nullptr;uint16_t*c=nullptr;bonsaikg4::BbDecl4*bb=nullptr;bonsaikg4::ValueRef4*v=nullptr;bonsaikg4::FeatureArgRef4*a=nullptr;bonsaikg4::Predicate4*q=nullptr;bonsaikg4::Lifecycle4*l=nullptr;bonsaikg4::Effect4*e=nullptr;~DevicePolicyOwner4(){if(n)cudaFree(n);if(c)cudaFree(c);if(bb)cudaFree(bb);if(v)cudaFree(v);if(a)cudaFree(a);if(q)cudaFree(q);if(l)cudaFree(l);if(e)cudaFree(e);}};
template<class T>static T*cp(const std::vector<T>&v){if(v.empty())return nullptr;T*d=nullptr;KAGCUDA_CHECK(cudaMalloc((void**)&d,v.size()*sizeof(T)));KAGCUDA_CHECK(cudaMemcpy(d,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));return d;}
static std::vector<std::string>split_tab(const std::string&s){std::vector<std::string>o;size_t p=0;for(;;){size_t q=s.find('\t',p);o.push_back(s.substr(p,q==std::string::npos?std::string::npos:q-p));if(q==std::string::npos)break;p=q+1;}return o;}
static std::vector<CaseHost>load_cases(const std::string&p){std::ifstream in(p);if(!in)throw std::runtime_error("cases");std::vector<CaseHost>o;std::string l;while(std::getline(in,l)){if(l.empty()||l[0]=='#')continue;auto z=split_tab(l);if(z.size()!=6&&z.size()!=7)throw std::runtime_error("case fields");CaseHost c;c.path=z[0];c.seat=std::stoi(z[1]);c.seed=std::stoull(z[2]);c.family=std::stoi(z[3]);c.protected_flag=std::stoi(z[4]);c.own_history=std::stoi(z[5]);if(z.size()==7)c.role=std::stoi(z[6]);o.push_back(c);}if(o.empty())throw std::runtime_error("empty cases");return o;}
static bonsaikg_v6::RoutePack load_legacy_pack(const std::string&path){std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("legacy");std::vector<uint8_t>raw((std::istreambuf_iterator<char>(in)),{});auto full=bonsaikg::sha256_bytes(raw);if(bonsaikg_v6::hash_hex(full)!=bonsaikg4_champion::LEGACY_ROUTE_PACK_SHA256)throw std::runtime_error("legacy hash");bonsaikg_v6::PackHeader h{};std::memcpy(&h,raw.data(),sizeof(h));size_t db=(size_t)h.route_count*sizeof(bonsaikg_v6::RouteDesc);bonsaikg_v6::RoutePack o;o.routes.resize(h.route_count);o.actions.resize(h.action_count);std::memcpy(o.routes.data(),raw.data()+sizeof(h),db);std::memcpy(o.actions.data(),raw.data()+sizeof(h)+db,o.actions.size()*sizeof(o.actions[0]));return o;}
struct DeviceBasePack{const bonsaikg_v6::RouteDesc*routes=nullptr;const bonsaikg_v6::PackedAction*actions=nullptr;int n=0;__device__ __forceinline__ const bonsaikg_v6::PackedAction*at(uint16_t route,int step)const{for(int i=0;i<n;++i)if(routes[i].route_id==route){int s=step;if(s<0)s=0;if(s>=routes[i].steps)s=routes[i].steps-1;return actions+routes[i].first+s;}return nullptr;}};
__device__ __forceinline__ void reconcile_feed(const int32_t*bb,int first,int count,Action&a){for(int u=0;u<count&&u<a.n_units;++u)if(bb[first+u]&&a.units[u].op==OP_FEED)a.units[u]=UnitAction{};}
__device__ __forceinline__ bool build_final_action(const ObservationView&raw,const DeviceBasePack&bp,const bonsaikg4_champion::CudaLegacyPack&lp,bonsaikg4_champion::CudaLegacyState&legacy,bonsaikg_v6::CudaEngineExploitState&exploit,const int32_t*bb,int feed_slot,int feed_count,Action&out){const auto*p=bp.at((uint16_t)bb[1],raw.step());if(!p)return false;bonsaikg_v6::materialize_cuda(*p,raw.farm(raw.player()).n_units(),out);bonsaikg4_champion::apply_legacy(raw,lp,legacy,out);bonsaikg_v6::apply_cuda_engine_exploits(raw,out,exploit,legacy.external_ok!=0,100);reconcile_feed(bb,feed_slot,feed_count,out);return true;}
__device__ __forceinline__ bool same_pos(const decltype(make_observation(*(Sim*)nullptr,0).farm(0))&f,int a,int b){return f.worker_x(a)==f.worker_x(b)&&f.worker_y(a)==f.worker_y(b);}
__device__ __forceinline__ UnitAction ua(uint8_t op,uint8_t arg=0,uint8_t n=1){UnitAction x{};x.op=op;x.arg=arg;x.n=n;return x;}
__device__ __forceinline__ bool one_shot(uint8_t crop){return crop==WHEAT||crop==CARROT||crop==MELON;}
__device__ __forceinline__ bool ripe_plant(const ObservationView&o,const Tile&t){if(t.kind!=T_PLANT||t.yield_units<=0||!one_shot(t.what))return false;return o.day()-t.planted_day>=D_CROPS[t.what].first_yield_day;}
// 0 BASE; 1 harvest->same-crop plant; 2 harvest->same-crop plant->water;
// 3 dig weed->wheat plant; 4 dig weed->wheat plant->water;
// 5 feed->care; 6 animal harvest->collect fertilizer; 7 build pasture->place cow;
// 8 build pasture->place sheep.  Compound actions require ascending unit indices because
// the official Python engine commits farmer then hands sequentially.
__device__ __forceinline__ uint16_t apply_compound(int mode,const ObservationView&o,Action&a,uint16_t&rew){if(mode<=0)return 0;auto f=o.farm(o.player());auto p=o.private_farm();int nu=f.n_units();
 for(int i=0;i<nu&&i<a.n_units;++i){int x=f.worker_x(i),y=f.worker_y(i);if(x<0||x>=BOARD||y<0||y>=BOARD)continue;const Tile&t=f.tile(x,y);
  for(int j=i+1;j<nu&&j<a.n_units;++j){if(!same_pos(f,i,j))continue;
   if((mode==1||mode==2)&&ripe_plant(o,t)&&p.seed(t.what)>0){a.units[i]=ua(OP_HARVEST);a.units[j]=ua(OP_PLANT,t.what);uint16_t n=2;if(mode==2){for(int k=j+1;k<nu&&k<a.n_units;++k)if(same_pos(f,i,k)){a.units[k]=ua(OP_WATER);n=3;break;}}rew+=n;return 1;}
   if((mode==3||mode==4)&&t.kind==T_WEED&&p.seed(WHEAT)>0){a.units[i]=ua(OP_DIG);a.units[j]=ua(OP_PLANT,WHEAT);uint16_t n=2;if(mode==4){for(int k=j+1;k<nu&&k<a.n_units;++k)if(same_pos(f,i,k)){a.units[k]=ua(OP_WATER);n=3;break;}}rew+=n;return 1;}
   if(mode==5&&t.has_animal&&!t.fed_today&&!t.cared_today&&p.inventory(i,WHEAT)>0){a.units[i]=ua(OP_FEED);a.units[j]=ua(OP_CARE);rew+=2;return 1;}
   if(mode==6&&t.has_animal&&t.yield_units>0&&t.fertilizer_available){a.units[i]=ua(OP_HARVEST);a.units[j]=ua(OP_COLLECT_FERTILIZER);rew+=2;return 1;}
   if((mode==7||mode==8)&&t.kind==T_EMPTY){uint8_t animal=mode==7?COW:SHEEP;if(p.inventory(j,animal)>0){a.units[i]=ua(OP_BUILD_PASTURE);a.units[j]=ua(OP_PLACE,animal);rew+=2;return 1;}if(p.inventory(i,animal)>0){a.units[i]=ua(OP_BUILD_PASTURE);a.units[j]=ua(OP_PLACE,animal);rew+=2;return 1;}}
  }
 }
 return 0;}
__global__ void kernel(Config cfg0,DeviceTables tables,bonsaikg4::PolicyView4 policy,DeviceBasePack bp,bonsaikg4_champion::CudaLegacyPack lp,const Action*opp,const OppDesc*od,const CaseDev*cases,int nc,int modes,int feed_slot,int feed_count,int32_t*bb,bonsaikg4::NodeState4*ns,bonsaikg4::RuntimeMeta4*meta,Sim*sims,Row*out){int job=blockIdx.x*blockDim.x+threadIdx.x,total=nc*modes;if(job>=total)return;int mode=job/nc,ci=job-mode*nc;const CaseDev c=cases[ci];Config cfg=cfg0;cfg.seed=c.seed;Sim&sim=sims[job];sim.init(cfg,&tables);bonsaikg4::RuntimeView4 st{policy.n_bb?bb+(size_t)job*policy.n_bb:nullptr,policy.n_state?ns+(size_t)job*policy.n_state:nullptr,meta+job};bonsaikg4::reset_runtime(policy,st);bonsaikg4_champion::CudaLegacyState legacy{};bonsaikg_v6::CudaEngineExploitState exploit{};bonsaikg4_champion::reset_legacy(legacy);bonsaikg_v6::reset_cuda_engine_exploits(exploit);uint16_t acts=0,rew=0,flags=0;while(!sim.st.done){int step=sim.st.step,os=1-c.seat;ObservationView ob=make_observation(sim,c.seat);bonsaikg4::ActionResult4 ign{};auto status=bonsaikg4::tick4(policy,st,bonsaikg4::CudaObservation4(ob),0,ign,nullptr);if(meta[job].fault||status!=bonsaikg4::SUCCESS){flags|=1;break;}Action ca{};if(!build_final_action(ob,bp,lp,legacy,exploit,st.blackboard,feed_slot,feed_count,ca)){flags|=2;break;}uint16_t q=apply_compound(mode,ob,ca,rew);acts+=q;Action oa{};OppDesc d=od[c.tape];if(d.count){int s=step<d.count?step:d.count-1;oa=opp[d.first+s];}oa.n_units=sim.st.farms[os].n_units;if(c.seat==0)sim.step_with_unit_counts(ca,sim.st.farms[0].n_units,oa,sim.st.farms[1].n_units);else sim.step_with_unit_counts(oa,sim.st.farms[0].n_units,ca,sim.st.farms[1].n_units);}Row r{};r.own_money=(int32_t)sim.st.farms[c.seat].money;r.opp_money=(int32_t)sim.st.farms[1-c.seat].money;r.activations=acts;r.rewrites=rew;r.flags=flags;out[job]=r;}
static void write_out(const std::string&p,const std::vector<Row>&r,int modes,int nc){std::ofstream o(p,std::ios::binary);Header h{{'B','4','C','W','1','\0','\0','\0'},1u,(uint32_t)modes,(uint32_t)nc};o.write((char*)&h,sizeof(h));o.write((char*)r.data(),r.size()*sizeof(r[0]));}
}
int main(int argc,char**argv){try{std::string controller,routes,legacy,casesp,outp;int feed_slot=5,feed_count=13,tpb=64,modes=9;for(int i=1;i<argc;++i){std::string z=argv[i];auto need=[&](){if(i+1>=argc)throw std::runtime_error("missing "+z);return std::string(argv[++i]);};if(z=="--controller")controller=need();else if(z=="--routes")routes=need();else if(z=="--legacy-routes")legacy=need();else if(z=="--cases")casesp=need();else if(z=="--out")outp=need();else if(z=="--modes")modes=std::stoi(need());else if(z=="--tpb")tpb=std::stoi(need());else throw std::runtime_error("unknown "+z);}if(controller.empty()||routes.empty()||legacy.empty()||casesp.empty()||outp.empty()||modes<1||modes>9)throw std::runtime_error("required args");auto owned=bonsaikg4::load_compiled4(controller);auto hp=owned.view();DevicePolicyOwner4 po;po.n=cp(owned.nodes);po.c=cp(owned.child_refs);po.bb=cp(owned.bb);po.v=cp(owned.values);po.a=cp(owned.feature_args);po.q=cp(owned.predicates);po.l=cp(owned.lifecycles);po.e=cp(owned.effects);auto dp=hp;dp.nodes=po.n;dp.child_refs=po.c;dp.bb=po.bb;dp.values=po.v;dp.feature_args=po.a;dp.predicates=po.q;dp.lifecycles=po.l;dp.effects=po.e;auto rp=bonsaikg_v6::RoutePack::load(routes),lg=load_legacy_pack(legacy);auto*dr=cp(rp.routes);auto*da=cp(rp.actions);auto*dlr=cp(lg.routes);auto*dla=cp(lg.actions);DeviceBasePack bp{dr,da,(int)rp.routes.size()};bonsaikg4_champion::CudaLegacyPack lp{dlr,dla,(int)lg.routes.size()};auto hc=load_cases(casesp);std::vector<Action>hoa;std::vector<OppDesc>hod;std::vector<CaseDev>hcd;for(const auto&c:hc){auto t=load_native_tape_json(c.path);int off=hoa.size();hoa.insert(hoa.end(),t.actions.begin(),t.actions.end());hod.push_back({off,(int)t.actions.size()});hcd.push_back({(int)hod.size()-1,c.seat,c.seed,c.family,c.protected_flag,c.own_history,c.role});}auto*doa=cp(hoa);auto*dod=cp(hod);auto*dc=cp(hcd);size_t jobs=(size_t)modes*hc.size();int32_t*dbb=nullptr;bonsaikg4::NodeState4*dns=nullptr;bonsaikg4::RuntimeMeta4*dm=nullptr;Sim*ds=nullptr;Row*dout=nullptr;if(hp.n_bb)KAGCUDA_CHECK(cudaMalloc((void**)&dbb,jobs*hp.n_bb*sizeof(int32_t)));if(hp.n_state)KAGCUDA_CHECK(cudaMalloc((void**)&dns,jobs*hp.n_state*sizeof(*dns)));KAGCUDA_CHECK(cudaMalloc((void**)&dm,jobs*sizeof(*dm)));KAGCUDA_CHECK(cudaMalloc((void**)&ds,jobs*sizeof(*ds)));KAGCUDA_CHECK(cudaMalloc((void**)&dout,jobs*sizeof(*dout)));configure_device();TablesOwner tables;Config cfg;cfg.episode_steps=720;cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);cudaEventRecord(a);kernel<<<(jobs+tpb-1)/tpb,tpb>>>(cfg,tables.dev,dp,bp,lp,doa,dod,dc,hc.size(),modes,feed_slot,feed_count,dbb,dns,dm,ds,dout);KAGCUDA_CHECK(cudaGetLastError());cudaEventRecord(b);cudaEventSynchronize(b);float ms=0;cudaEventElapsedTime(&ms,a,b);std::vector<Row>hr(jobs);KAGCUDA_CHECK(cudaMemcpy(hr.data(),dout,jobs*sizeof(Row),cudaMemcpyDeviceToHost));int bad=0;for(auto&r:hr)bad+=r.flags!=0;write_out(outp,hr,modes,hc.size());std::cout<<"modes="<<modes<<" cases="<<hc.size()<<" games="<<jobs<<" gpu_ms="<<ms<<" games_s="<<(jobs/(ms/1000.0))<<" bad="<<bad<<"\n";return bad?1:0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 2;}}
